// ==========================================
// Konfiguration
// ==========================================

const rate = 6500;       // Nachrichten pro Sekunde
const value = 42;       // Payload der erzeugten Nachrichten

// Generator-Takt
const tickMs = 10;


// ==========================================
// Eingang auswerten
// ==========================================

// START
if (msg.payload === true) {

    // Läuft bereits?
    if (context.get("running")) {
        node.warn("Load Generator läuft bereits");
        return null;
    }

    context.set("running", true);

    const startTime = Date.now();
    let sent = 0;


    // ==========================================
    // Generator
    // ==========================================

    function tick() {

        // Wurde inzwischen gestoppt?
        if (!context.get("running")) {
            node.status({
                fill: "red",
                shape: "ring",
                text: `gestoppt (${sent} gesendet)`
            });

            return;
        }

        const now = Date.now();
        const elapsedMs = now - startTime;

        // Anzahl Nachrichten, die laut Sollfrequenz
        // bis jetzt gesendet worden sein müssten
        const targetSent = Math.floor(
            elapsedMs * rate / 1000
        );

        // Fehlende Nachrichten nachholen
        const batchSize = targetSent - sent;

        if (batchSize > 0) {

            const messages = new Array(batchSize);

            for (let i = 0; i < batchSize; i++) {
                messages[i] = {
                    payload: value
                };
            }

            node.send([messages]);

            sent += batchSize;
        }


        // ==========================================
        // Nächsten Tick absolut ausrichten
        // ==========================================

        const nextTickNumber =
            Math.floor(elapsedMs / tickMs) + 1;

        const nextTarget =
            startTime + nextTickNumber * tickMs;

        const delay =
            Math.max(0, nextTarget - Date.now());

        setTimeout(tick, delay);
    }


    // ==========================================
    // Start
    // ==========================================

    node.status({
        fill: "green",
        shape: "dot",
        text: `${rate} msg/s`
    });

    tick();

    return null;
}


// ==========================================
// STOP
// ==========================================

if (msg.payload === false) {

    context.set("running", false);

    node.status({
        fill: "red",
        shape: "ring",
        text: "gestoppt"
    });

    return null;
}


// Andere Eingaben ignorieren
return null;

if (msg.topic !== "benchmark") {
    return null;
}

const result = msg.payload;
msg.payload = JSON.stringify(result, null, 2);

return msg;

